WITH filtered_shipments AS (SELECT * FROM shipments WHERE order_id = 29 OR carrier = 'DHL'), Agg AS (SELECT CASE WHEN cost >= 83 THEN 'high' WHEN cost >= 22 THEN 'mid' ELSE 'low' END cost_bucket, MONTH(delivered_date) delivered_month, MIN(shipped_date) min_shipped_date, SORT_ARRAY(COLLECT_SET(status)) status_list FROM filtered_shipments GROUP BY CASE WHEN cost >= 83 THEN 'high' WHEN cost >= 22 THEN 'mid' ELSE 'low' END, MONTH(delivered_date)) SELECT cost_bucket, delivered_month, min_shipped_date, status_list FROM Agg ORDER BY cost_bucket;
